#!/usr/bin/env python3
"""Build book13 from its intact two-part handoff and separately verified sources."""
import argparse,hashlib,json,re
from html import escape as e
from pathlib import Path
from PIL import Image
from lxml import html
R=Path(__file__).resolve().parents[1];D=R/'docs/five-roots-powers';S=R/'five-roots-powers'
def read(name):return json.loads((D/name).read_text())
def sec(value):
 m,s=map(int,value.split(':'));return m*60+s
def validate():
 for name,row in read('receipt.json').items():
  raw=(D/name).read_bytes();assert len(raw)==row['bytes'] and hashlib.sha256(raw).hexdigest()==row['sha256'],name
 story=read('storyboard.json');assert len(story)==10 and sum(len(s['cues']) for s in story)==74
 cues=[c for s in story for c in s['cues']];assert all(sec(c['end'])>sec(c['start']) for c in cues)
 assert all(cues[n]['end']==cues[n+1]['start'] for n in range(73))
 for i,s in enumerate(story,1):assert s['scene'].startswith(f'S{i:02}｜') and s['asset']==f'assets/S{i:02}.png'
 for f in read('source-files.json'):assert hashlib.sha256((D/f['local']).read_bytes()).hexdigest()==f['sha256']
 print('Original14files/11images,10scenes/74timed cues and5canonical sources verified')
def book():
 story=read('storyboard.json');labels=read('overlay-layout.json')['overlays'];cat=read('scripture-catalog.json');plan=read('reader-plan.json');pages=[];scenes=[]
 for original in story:
  sid=original['scene'][:3];title=original['scene'].split('｜',1)[1].split('（')[0]
  with Image.open(D/original['asset']) as im:dimensions=list(im.size)
  scenes.append({'id':sid,'title':title,'start':len(pages),'image':original['asset'],'alt':title,'dimensions':dimensions,'artOverlay':labels[sid],'summaryRows':[],'overlaySpecification':original['overlay']})
  for local,(cue,mapping) in enumerate(zip(original['cues'],plan[sid]),1):
   assert mapping['paragraphId']==f'P{len(pages)+1:03}'
   pages.append({'scene':sid,'title':title,'paragraphId':mapping['paragraphId'],'paragraphNumber':local,'startTime':cue['start'],'endTime':cue['end'],'startSeconds':sec(cue['start']),'endSeconds':sec(cue['end']),'videoUrl':'https://www.youtube.com/watch?v=EzZOF8vQS2k&t='+str(sec(cue['start']))+'s','lines':[cue['text']],'quotes':[cat[q] for q in mapping['quoteIds']],'context':None,'sourceNote':original['scripture'] if sid=='S02' else None,'image':'../assets/'+sid+'.webp','dimensions':dimensions})
 pages.append({'scene':'S10','title':'閱讀說明','paragraphNumber':5,'lines':[],'quotes':[],'context':None,'sourceNote':None,'image':None,'dimensions':None,'afterword':True,'textSummary':[{'title':'經典依據','paragraphs':['本繪本依《相應部》第48.43經及《雜阿含經》第646、647、654、675經製作。小貓、中央島與樹根抗風的畫面是故事表現；河流譬喻及棟樑譬喻可對讀原經，解讀仍請以原經文為準。','也希望這本繪本能成為您走入經藏的起點。'],'rows':[]}]})
 return S/'book/book-data.js','// Generated by scripts/build-five-roots-powers.py; original handoff preserved.\nconst BOOK = '+json.dumps({'title':'五根五力','video':{'url':'https://youtu.be/EzZOF8vQS2k','durationSeconds':410.73,'included':False},'timingAccuracy':'seconds-approximate-subtitle-samples-not-audio-verified','scenes':scenes,'pages':pages},ensure_ascii=False,indent=2)+';\n'
def guide():
 template=html.parse(str(R/'anapana/index.html'));icons=[html.tostring(x,encoding='unicode') for x in template.xpath('//article[@id="sa803"]//a[contains(@class,"source-button")]/svg')]
 def button(url,label,kind,i):return '<a class="source-button source-button--'+kind+'" href="'+e(url,quote=True)+'" target="_blank" rel="noopener noreferrer">'+icons[i]+'<span>'+label+'</span></a>'
 text='''<!doctype html><html lang="zh-Hant-TW"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>五根五力｜SutraZen 主題導讀</title><meta name="description" content="跟著小貓，認識信、精進、念、定、慧，對讀五根五力與中央島河流、棟樑譬喻。"><link rel="stylesheet" href="guide.css"><link rel="stylesheet" href="../guide-header.css"><link rel="stylesheet" href="../guide-ui.css"></head><body class="topic-guide"><header class="guide-header"><div class="guide-header-inner"><span class="guide-brand">SutraZen</span><a class="guide-return" href="../index.html">回三十七道品修道地圖</a></div></header><main class="wrap guide-content"><p class="eyebrow">佛法繪本 · 主題導讀</p><h1>五根五力</h1><p class="lead"><strong>同樣的五種能力，從不同面向觀察。</strong>信、精進、念、定、慧，既是修行的根基，也是在障礙前不易動搖的力量。跟著小貓走過中央島、護苗的園地與平靜水面，對照五種能力在修行中的作用。</p><section class="book-preview" aria-labelledby="book-heading"><h2 id="book-heading">翻頁繪本 · 五根五力篇</h2><p class="intro">一頁一頁閱讀完整故事，對照插畫與經文。</p><a class="book-cover" href="book/index.html" aria-label="開始翻閱五根五力"><img src="assets/S01.webp" width="1672" height="941" alt="晴天中央島，河水從島嶼兩側流過"><span class="book-cover-action"><span>開始翻閱 →</span></span></a></section><section><h2>一條河，五種能力</h2><p>《相應部》第48.43經以中央島旁的水流說明：可以從一條水流或兩條水流來看同一條河；五根與五力也可從不同面向說同樣五法。樹根站穩與抗風的畫面，則是本篇影片用來幫助理解的教學譬喻。</p><div class="chapter-grid">'''
 chapters=[('S01','中央島與兩道水流','同一條河，可以從不同角度觀看。'),('S02','根與力的作用','建立修行的根基，也培養不易動搖的力量。'),('S03','五根地圖','五種能力對應修行中的重要法門。'),('S04','信根','四不壞淨：對佛、法、僧、戒的清淨信心。'),('S05','精進根','四正斷：斷惡、修善，如除草與護苗。'),('S06','念根','四念處：清楚覺察身、受、心、法。'),('S07','定根','四禪：收攝、安住，不隨散亂而轉。'),('S08','慧根','四聖諦：如實了解苦及其止息的道路。'),('S09','五力','同樣五法，在障礙前保持穩固。'),('S10','慧為其首','棟樑攝持眾材，五根相互成就。')]
 for sid,title,copy in chapters:text+='<a href="book/index.html?scene='+sid+'"><strong>'+title+'</strong><span>'+copy+'</span></a>'
 text+='''</div></section><section id="video" class="guide-video"><h2>療癒系佛法繪本 · 五根五力篇</h2><div class="video"><iframe title="療癒系佛法繪本 · 五根五力篇" src="https://www.youtube.com/embed/EzZOF8vQS2k" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe></div></section><section id="sources" class="refs" aria-labelledby="sources-heading"><h2 id="sources-heading">閱讀原經｜經典出處與原文對讀</h2>'''
 for source in read('verified-sources.json')['sources']:
  classical=source['id'].startswith('sa');text+='<article class="source-entry" id="'+source['id']+'">'+''.join('<span class="source-anchor" id="'+q+'"></span>' for q in source['quoteIds'])+'<p class="eyebrow">五根五力 · 經典出處</p><h3>'+source['title']+'</h3><p class="source-meta">'+source['meta']+'</p><div class="source-actions">'+button(source['primary'],'漢譯經文' if classical else '中譯經文','original',0)+button(source['comparison'],source['comparisonLabel'],'annotation',1)+'</div><div class="source-providers">'+''.join('<p>'+e(p)+'</p>' for p in source['providers'])+'</div><div class="source-text">'
  for n,excerpt in enumerate(source['excerpts']):
   title={'sa647':['信根','精進根','念根','定根','慧根'],'sn48.43':['中央島與河流','一條水流','兩條水流','同樣五法'],'sa646':['五根與修行法門'],'sa675':['五力與修行法門'],'sa654':['棟樑譬喻']}[source['id']][n]
   text+='<h4 class="source-text-heading">'+title+'</h4><blockquote><p>'+e(excerpt)+'</p></blockquote>'
  text+='</div></article>'
 return S/'index.html',text+'</section></main></body></html>\n'
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');a=p.parse_args();validate()
 for path,body in [book(),guide()]:
  if a.check:assert path.read_text()==body,path
  else:path.write_text(body)
 print('10 scenes /74 intact timed cues /14 quote cards /5 image overlays /75 reader pages')
